q(3,'あ：たて 3cm、横 4cm、高さ 5cm の 直方体。い：1辺が 4cmの 立方体。う：たて 2cm、横 5cm、高さ 6cm の 直方体。体積が いちばん 大きいのは どれですか。','い',[('あ','60cm³で いと 同じ くらいと 見た'),('う','う の 高さが 大きいから と かんがえた'),('ぜんぶ 同じ 体積','数が 近いから 同じと かんがえた')],
  'あ：3 × 4 × 5 = 60、い：4 × 4 × 4 = 64、う：2 × 5 × 6 = 60\nいが いちばん 大きい。\nこたえ い','3つとも 体積を 求めて くらべよう。',"max([('あ',3*4*5),('い',4*4*4),('う',2*5*6)],key=lambda t:t[1])[0]",'{}')
q(3,'体積が 48cm³の 直方体が あります。たてが 4cm、高さが 3cmの とき、横は 何cmですか。','4cm',[('12cm','48 ÷ 4 と かんがえた'),('16cm','48 ÷ 3 と かんがえた'),('41cm','48 − 4 − 3 と かんがえた')],
  'たて × 高さ ＝ 4 × 3 = 12。\n48 ÷ 12 = 4\nたしかめ：4 × 4 × 3 = 48\nこたえ 4cm','たてと 高さを かけてから わろう。',"48//(4*3)",'{}cm')
q(3,'立方体の 体積が 27cm³です。1辺の 長さは 何cmですか。','3cm',[('9cm','27 ÷ 3 と かんがえた'),('24cm','27 − 3 と かんがえた'),('27cm',None)],
  '3 × 3 × 3 = 27 だから 1辺は 3cm。\nこたえ 3cm','同じ 数を 3回 かけて 27に なる 数を さがそう。',"[n for n in range(1,30) if n**3==27][0]",'{}cm')
q(3,'たて 3cm、横 4cm、高さ 5cmの 直方体の 高さだけを 2倍の 10cmに しました。体積は 何cm³ですか。','120cm³',[('60cm³','変わらないと かんがえた'),('65cm³','5を たした'),('130cm³','高さに 10を かけて 3 × 4 を たした')],
  '3 × 4 × 10 = 120\nもとの 体積 60cm³の 2倍に なる。\nこたえ 120cm³','高さが 10cmに なった 直方体の 体積を 求めよう。',"3*4*10",'{}cm³')
q(4,'立方体の 1辺の 長さを 2倍に すると、体積は もとの 何倍に なりますか。','8倍',[('2倍','1辺と 同じ 2倍と かんがえた'),('4倍','2 × 2 と かんがえた'),('6倍','2 × 3 と かんがえた')],
  '1辺が 3cmの とき 27cm³。1辺が 6cmの とき 6 × 6 × 6 = 216cm³。\n216 ÷ 27 = 8\nこたえ 8倍','1辺が 2cmと 4cmの 立方体で ためしてみよう。',"(6**3)//(3**3)",'{}倍')
q(4,'たて 5cm、横 6cm の 直方体の 体積が 150cm³です。高さは 何cmですか。','5cm',[('25cm','150 ÷ 6 と かんがえた'),('30cm','5 × 6 を こたえた'),('11cm','5 + 6 と かんがえた')],
  '1だん目は 5 × 6 = 30(こ)。\n150 ÷ 30 = 5\nたしかめ：5 × 6 × 5 = 150\nこたえ 5cm','1だん目の 立方体の 数から 考えよう。',"150//(5*6)",'{}cm')
q(4,'たて 6cm、横 4cm、高さ 6cmの はこに、1辺が 2cmの 立方体を すきまなく つめます。何こ つめますか。','18こ',[('144こ','はこの 体積を そのまま こたえた'),('36こ','8で なく 4で わった'),('72こ','8で なく 2で わった')],
  'たては 6 ÷ 2 = 3(こ)、横は 4 ÷ 2 = 2(こ)、高さは 6 ÷ 2 = 3(こ)。\n3 × 2 × 3 = 18\nこたえ 18こ','たて・横・高さに それぞれ 何こ ならぶか 考えよう。',"(6//2)*(4//2)*(6//2)",'{}こ')
q(4,'直方体の たてを 2倍、横を 2倍に します。高さは そのままです。体積は もとの 何倍に なりますか。','4倍',[('2倍','2倍が 2つだから 2倍と かんがえた'),('8倍','高さも 2倍と かんがえた'),('6倍','2 + 2 + 2 と かんがえた')],
  'たて 3cm、横 4cm、高さ 5cmで ためす。\nもとは 3 × 4 × 5 = 60。あとは 6 × 8 × 5 = 240。\n240 ÷ 60 = 4\nこたえ 4倍','数を 入れて ためして みよう。',"(6*8*5)//(3*4*5)",'{}倍')
